-        configurator.SetBusFactory(new AmazonSqsRegistrationBusFactory(configure));
+        services.TryAddEnumerable(ServiceDescriptor.Singleton<ITransportSendFailureClassifier, AmazonSqsSendFailureClassifier>());
     }

